(()=>{'use strict';const A=[...document.querySelectorAll('textarea')],K='economia-v2',w=(m,e)=>console.warn('[economia] '+m,e||''),g=()=>{try{return JSON.parse(localStorage.getItem(K)||'{}')}catch(e){w('storage',e);return{}}},save=()=>{try{localStorage.setItem(K,JSON.stringify(Object.fromEntries(A.map(x=>[x.id,x.value]))))}catch(e){w('storage',e)}},d=g();A.forEach(x=>x.value=d[x.id]||'');document.addEventListener('input',e=>{if(e.target.matches('textarea'))save()});document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action;if(a==='clear'){A.forEach(x=>x.value='');try{localStorage.removeItem(K)}catch(e){w('storage',e)}}else if(a==='print')print();else if(a==='download'){let v=A.map(x=>x.id+'\n'+x.value).join('\n\n'),u=URL.createObjectURL(new Blob([v],{type:'text/plain;charset=utf-8'})),x=document.createElement('a');x.href=u;x.download='respuestas-economia-imperio.txt';x.click();setTimeout(()=>URL.revokeObjectURL(u),0)}});addEventListener('error',e=>w('error',e.error||e.message));addEventListener('unhandledrejection',e=>w('rejection',e.reason));if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./economia-sw.js').catch(e=>w('cache',e)),{once:true})})();
